use super::*;
fn w(id:usize,raw:&str,x0:f32,y0:f32,x1:f32,y1:f32,status:WordStatus)->Word {Word{source_box: [x0, y0, x1, y1],id,raw:raw.into(),text:crate::normalize::word_text(raw),x0,y0,x1,y1,status}}
fn sample()->(Vec<Unit>,Vec<Word>){let ws=vec![w(0,"比較液。",0.,0.,32.,8.,WordStatus::Used),w(1,"Ｌ",32.,1.5,38.,7.8,WordStatus::Used),w(2,"\u{E61C}",38.05,0.,46.05,8.2,WordStatus::Empty),w(3,"グルタミン酸を加える",0.,12.,80.,20.,WordStatus::Used)];let u=vec![Unit::Plain(vec![Line::text("比較液。Ｌ".into(),vec![0,1]),Line::text("グルタミン酸を加える".into(),vec![3])])];(u,ws)}
fn lines(u:&[Unit])->&Vec<Line>{match &u[0]{Unit::Plain(l)=>l,_=>unreachable!()}}
fn signature(u:&[Unit],ws:&[Word])->String{serde_json::to_string(&(lines(u),ws)).unwrap()}
#[test]fn native_terminal_hyphen_is_only_added_to_existing_prefix_line(){let(mut u,mut ws)=sample();let before=ws.clone();restore(&mut u,&mut ws);assert_eq!(lines(&u)[0].text,"比較液。Ｌ－");assert_eq!(lines(&u)[0].words,vec![0,1,2]);assert_eq!(ws[2].text,"－");assert_eq!(ws[2].status,WordStatus::Used);for i in 0..4{assert_eq!(ws[i].raw,before[i].raw);assert_eq!((ws[i].x0,ws[i].y0,ws[i].x1,ws[i].y1),(before[i].x0,before[i].y0,before[i].x1,before[i].y1));}let b=signature(&u,&ws);restore(&mut u,&mut ws);assert_eq!(signature(&u,&ws),b);}
#[test]fn d_prefix_and_repaired_body_are_not_rebuilt(){let(mut u,mut ws)=sample();ws[1].raw="Ｄ".into();ws[1].text="Ｄ".into();if let Unit::Plain(l)=&mut u[0]{l[0].text="既修復ⅲ 1/2 ㎡ 比較液。Ｄ".into()}restore(&mut u,&mut ws);assert_eq!(lines(&u)[0].text,"既修復ⅲ 1/2 ㎡ 比較液。Ｄ－");}
#[test]fn wide_gap_different_baseline_or_non_square_bar_is_rejected(){for case in 0..4{let(mut u,mut ws)=sample();match case{0=>{ws[2].x0+=3.;ws[2].x1+=3.},1=>{ws[2].y0+=5.;ws[2].y1+=5.},2=>ws[2].x1+=10.,_=>ws[2].x0-=3.};let b=signature(&u,&ws);restore(&mut u,&mut ws);assert_eq!(signature(&u,&ws),b,"case{case}");}}
#[test]fn next_column_header_or_nonchemical_continuation_is_rejected(){for case in 0..4{let(mut u,mut ws)=sample();match case{0=>{ws[3].x0+=100.;ws[3].x1+=100.},1=>{ws[3].y0+=60.;ws[3].y1+=60.},2=>{if let Unit::Plain(l)=&mut u[0]{l[1].text="第三条".into()}},_=>{if let Unit::Plain(l)=&mut u[0]{l[1].text="グ 請求額".into()}}};let b=signature(&u,&ws);restore(&mut u,&mut ws);assert_eq!(signature(&u,&ws),b,"case{case}");}}
#[test]fn used_or_owned_dash_duplicate_prefix_or_third_overlapping_word_is_rejected(){for case in 0..4{let(mut u,mut ws)=sample();match case{0=>ws[2].status=WordStatus::Used,1=>{if let Unit::Plain(l)=&mut u[0]{l[1].words.push(2)}},2=>{if let Unit::Plain(l)=&mut u[0]{l.push(Line::text("Ｌ".into(),vec![1]))}},_=>{ws.push(w(4,"\u{E952}",38.05,0.,46.05,8.2,WordStatus::Empty))}};let b=signature(&u,&ws);restore(&mut u,&mut ws);assert_eq!(signature(&u,&ws),b,"case{case}");}}
#[test]fn only_a_single_unmodified_terminal_l_or_d_word_is_eligible(){for case in 0..4{let(mut u,mut ws)=sample();match case{0=>{ws[1].raw="Ｘ".into();ws[1].text="Ｘ".into()},1=>ws[1].raw="\u{E952}Ｌ".into(),2=>ws[1].text="再構成Ｌ".into(),_=>{if let Unit::Plain(l)=&mut u[0]{l[0].text.push_str(" 次の語")}}};let b=signature(&u,&ws);restore(&mut u,&mut ws);assert_eq!(signature(&u,&ws),b,"case{case}");}}
#[test]fn absent_original_dash_is_never_inferred(){let(mut u,mut ws)=sample();ws.truncate(2);if let Unit::Plain(l)=&mut u[0]{l.pop();}let b=signature(&u,&ws);restore(&mut u,&mut ws);assert_eq!(signature(&u,&ws),b);}
#[test]fn lower_decoration_overhang_does_not_masquerade_as_same_baseline_text(){let(mut u,mut ws)=sample();ws.push(w(4,"\u{E005}\u{E005}",32.,5.7,46.05,13.9,WordStatus::Empty));restore(&mut u,&mut ws);assert_eq!(lines(&u)[0].text,"比較液。Ｌ－");assert_eq!(ws[4].status,WordStatus::Empty);assert_eq!(ws[4].text,"");}
